Lemma rauxv_ok_pres : forall C m m' B,
  rauxv_ok m B -> rpres_except C m m' ->
  (forall a, B <= a -> ~ C a) -> (forall a, RAUXV_CELL <= a < RAUXV_CELL + 8 -> ~ C a) ->
  rauxv_ok m' B.
Proof.
ltac2:(KReplay.run1 (kr_t_RMallocKit_A ()) ["CEIL_WRAP_1"] (Mh_0096_blobs1.kr_b_010 ())). Qed.

