Lemma rst0_region rid r : (s_regions st0) !! rid = Some r ->
  0 <= r_base r /\ r_base r + round_up_pg (r_len r) <= alloc_ceiling
  /\ (r_base r + round_up_pg (r_len r) <= 0x10000 \/ 0x39000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x39000 \/ 0xc3000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0xc3000 \/ 0xca000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0xca000 \/ 0xfe000 <= r_base r).
Proof.
